CreateBitmapRepresentation(CFAllocatorRef alloc) const;	// CFMutableCharacterSet wrappings	static CFMutableCharacterSetRef CreateMutable(CFAllocatorRef alloc);	static CFMutableCharacterSetRef CreateMutableCopy(CFAllocatorRef alloc, CFCharacterSetRef theSet);	void AddCharactersInRange(CFRange theRange);	void RemoveCharactersInRange(CFRange theRange);	void AddCharactersInString(CFStringRef theString);	void RemoveCharactersInString(CFStringRef theString);	void Union(CFCharacterSetRef theOtherSet);	void Intersect(CFCharacterSetRef theOtherSet);	void Invert();};//========================================================================================// CAutoCFCharacterSet_AC//========================================================================================class CAutoCFCharacterSet_AC : public TemplateAutoRef_AC<CFCharacterSetRef>{public:	CAutoCFCharacterSet_AC();	CAutoCFCharacterSet_AC(CFCharacterSetRef theSet);	CAutoCFCharacterSet_AC(CFCharacterSetPredefinedSet theSetIdentifier);	CAutoCFCharacterSet_AC(CFRange theRange);	CAutoCFCharacterSet_AC(CFStringRef theString);	CAutoCFCharacterSet_AC(CFDataRef theData);	CAutoCFCharacterSet_AC(const TemplateAutoRef_AC<CFCharacterSetRef>& from);	~CAutoCFCharacterSet_AC();};//========================================================================================// CAutoCFMutableCharacterSet_AC//========================================================================================class CAutoCFMutableCharacterSet_AC : public TemplateAutoRef_AC<CFMutableCharacterSetRef>{public:	CAutoCFMutableCharacterSet_AC();	CAutoCFMutableCharacterSet_AC(CFMutableCharacterSetRef theSet);	CAutoCFMutableCharacterSet_AC(CFAllocatorRef alloc);	CAutoCFMutableCharacterSet_AC(CFCharacterSetRef theSet);	CAutoCFMutableCharacterSet_AC(const TemplateAutoRef_AC<CFMutableCharacterSetRef>& from);	~CAutoCFMutableCharacterSet_AC();};//========================================================================================// __CFCharacterSet//========================================================================================inline /*static*/ CFCharacterSetRef __CFCharacterSet::GetPredefined(CFCharacterSetPredefinedSet theSetIdentifier){	return CFCharacterSetGetPredefined(theSetIdentifier);}inline bool __CFCharacterSet::IsCharacterMember(UniChar theChar) const{	return CFCharacterSetIsCharacterMember(this, theChar);}inline CFDataRef __CFCharacterSet::CreateBitmapRepresentation(CFAllocatorRef alloc) const{	return CFCharacterSetCreateBitmapRepresentation(alloc, this);}inline void __CFCharacterSet::AddCharactersInRange(CFRange theRange){	CFCharacterSetAddCharactersInRange(this, theRange);}inline void __CFCharacterSet::RemoveCharactersInRange(CFRange theRange){	CFCharacterSetRemoveCharactersInRange(this, theRange);}inline void __CFCharacterSet::AddCharactersInString(CFStringRef theString){	CFCharacterSetAddCharactersInString(this, theString);}inline void __CFCharacterSet::RemoveCharactersInString(CFStringRef theString){	CFCharacterSetRemoveCharactersInString(this, theString);}inline void __CFCharacterSet::Union(CFCharacterSetRef theOtherSet){	CFCharacterSetUnion(this, theOtherSet);}inline void __CFCharacterSet::Intersect(CFCharacterSetRef theOtherSet){	CFCharacterSetIntersect(this, theOtherSet);}inline void __CFCharacterSet::Invert(){	CFCharacterSetInvert(this);}//========================================================================================// CAutoCFCharacterSet_AC//========================================================================================inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC()	:	TemplateAutoRef_AC<CFCharacterSetRef>(NULL){}inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC(CFCharacterSetRef theSet)	:	TemplateAutoRef_AC<CFCharacterSetRef>(theSet){}inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC(CFCharacterSetPredefinedSet theSetIdentifier)	:	TemplateAutoRef_AC<CFCharacterSetRef>(CFCharacterSetRef(theSetIdentifier)){}inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC(CFRange theRange)	:	TemplateAutoRef_AC<CFCharacterSetRef>(__CFCharacterSet::CreateWithCharactersInRange(NULL, theRange)){}inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC(CFStringRef theString)	:	TemplateAutoRef_AC<CFCharacterSetRef>(__CFCharacterSet::CreateWithCharactersInString(NULL, theString)){}inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC(CFDataRef theData)	:	TemplateAutoRef_AC<CFCharacterSetRef>(__CFCharacterSet::CreateWithBitmapRepresentation(NULL, theData)){}inline CAutoCFCharacterSet_AC::CAutoCFCharacterSet_AC(const TemplateAutoRef_AC<CFCharacterSetRef>& from)	:	TemplateAutoRef_AC<CFCharacterSetRef>(from){}inline CAutoCFCharacterSet_AC::~CAutoCFCharacterSet_AC(){}//========================================================================================// CAutoCFMutableCharacterSet_AC//========================================================================================inline CAutoCFMutableCharacterSet_AC::CAutoCFMutableCharacterSet_AC()	:	TemplateAutoRef_AC<CFMutableCharacterSetRef>(){}inline CAutoCFMutableCharacterSet_AC::CAutoCFMutableCharacterSet_AC(CFMutableCharacterSetRef theSet)	:	TemplateAutoRef_AC<CFMutableCharacterSetRef>(theSet){}inline CAutoCFMutableCharacterSet_AC::CAutoCFMutableCharacterSet_AC(CFAllocatorRef alloc)	:	TemplateAutoRef_AC<CFMutableCharacterSetRef>(__CFCharacterSet::CreateMutable(alloc)){}inline CAutoCFMutableCharacterSet_AC::CAutoCFMutableCharacterSet_AC(CFCharacterSetRef theSet)	:	TemplateAutoRef_AC<CFMutableCharacterSetRef>(__CFCharacterSet::CreateMutableCopy(NULL, theSet)){}inline CAutoCFMutableCharacterSet_AC::CAutoCFMutableCharacterSet_AC(const TemplateAutoRef_AC<CFMutableCharacterSetRef>& from)	:	TemplateAutoRef_AC<CFMutableCharacterSetRef>(from){}inline CAutoCFMutableCharacterSet_AC::~CAutoCFMutableCharacterSet_AC(){}#endif // __CCFCharacterSet_AC__